def list_instruction_templates(
    *,
    activity_type: Optional[str] = None,
    subject_code: Optional[str] = None,
    tags: Optional[List[str]] = None,
) -> List[I18nTemplate]:
    out: List[I18nTemplate] = []
    for tpl in TEMPLATES:
        if activity_type and tpl.get("activity_type") != activity_type:
            continue
        if subject_code is not None and tpl.get("subject_code") != subject_code:
            continue
        if tags:
            tpl_tags = set(tpl.get("tags") or [])
            if not set(tags).issubset(tpl_tags):
                continue
        out.append(tpl)
    return out


def instruction_key(activity_slug: str, subject_code: Optional[str]) -> str:
    if subject_code:
        return f"activity.{activity_slug}.instruction.{subject_code}"
    return f"activity.{activity_slug}.instruction.generic"
